"use client";

import { useState } from "react";
import UploadCard from "@/components/scan/UploadCard";
import ResultsPanel from "@/components/scan/ResultsPanel";
import { MOCK_SCAN } from "@/data/mockScan";

export default function ScanPage() {
  const [previewUrl, setPreviewUrl] = useState("");
  const [selectedFile, setSelectedFile] = useState(null);
  const [isLoading, setIsLoading] = useState(false);
  const [activeTab, setActiveTab] = useState("overview");
  const [results, setResults] = useState(null);
  const [error, setError] = useState("");

  const handleFileSelect = (file) => {
    if (!file || !file.type.startsWith("image/")) {
      setError("Please select a valid image file.");
      return;
    }

    setError("");
    setSelectedFile(file);
    setResults(null);

    const reader = new FileReader();
    reader.onload = (event) => {
      setPreviewUrl(event.target?.result ?? "");
    };
    reader.readAsDataURL(file);
  };

  const handleScan = async () => {
    if (!selectedFile) return;

    setIsLoading(true);
    setError("");

    await new Promise((resolve) => setTimeout(resolve, 700));

    setResults(MOCK_SCAN);
    setActiveTab("overview");
    setIsLoading(false);
  };

  return (
    <main className="relative min-h-screen overflow-hidden px-4 py-12">
      <div className="pointer-events-none absolute inset-0">
        <div className="absolute -left-24 top-12 h-72 w-72 rounded-full bg-emerald-200/40 blur-3xl"></div>
        <div className="absolute right-0 top-0 h-80 w-80 rounded-full bg-amber-200/40 blur-3xl"></div>
        <div className="absolute bottom-0 left-1/3 h-72 w-72 rounded-full bg-sky-200/30 blur-3xl"></div>
      </div>

      <div className="relative mx-auto flex w-full max-w-4xl flex-col gap-6">
        <UploadCard
          onFileSelect={handleFileSelect}
          previewUrl={previewUrl}
          isLoading={isLoading}
          canScan={Boolean(selectedFile)}
          onScan={handleScan}
          error={error}
        />

        <ResultsPanel
          results={results}
          activeTab={activeTab}
          onTabChange={setActiveTab}
        />
      </div>
    </main>
  );
}
